PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE springs (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  slug TEXT NOT NULL UNIQUE,
  lat REAL NOT NULL,
  lon REAL NOT NULL,
  elevation_ft INTEGER,
  temperature_f INTEGER,
  access_type TEXT NOT NULL,
  development TEXT NOT NULL DEFAULT 'primitive',
  chemistry TEXT,
  state TEXT NOT NULL,
  region TEXT NOT NULL,
  fs_road TEXT,
  description TEXT,
  image_url TEXT,
  source_temperature_c REAL,
  chemistry_source TEXT,
  chemistry_sampled_on TEXT,
  chemistry_level TEXT DEFAULT 'basic',
  chemistry_details TEXT DEFAULT '{}',
  nearby_town TEXT,
  distance_to_town_mi REAL,
  trailhead_lat REAL,
  trailhead_lon REAL,
  fees TEXT,
  fee_amount_usd REAL,
  reservation_required INTEGER DEFAULT 0,
  reservation_url TEXT,
  cell_service TEXT DEFAULT 'unknown',
  seasonal_open TEXT,
  seasonal_close TEXT,
  seasonal_notes TEXT,
  dog_policy TEXT DEFAULT 'unknown',
  clothing_policy TEXT DEFAULT 'unknown',
  ada_accessible INTEGER DEFAULT 0,
  pool_count INTEGER,
  water_flow TEXT DEFAULT 'unknown',
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
, vehicle_requirement TEXT DEFAULT 'any', permit_types TEXT DEFAULT '[]', crowding_pattern TEXT DEFAULT 'unknown', ferry_dependent INTEGER DEFAULT 0, ferry_route TEXT, winter_access_notes TEXT, nwac_zone TEXT, is_soakable INTEGER DEFAULT 1, is_confirmed INTEGER DEFAULT 0, soaking_temp_f INTEGER, road_type TEXT, status TEXT DEFAULT 'open', last_verified TEXT);
CREATE TABLE d1_migrations(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE blog_posts (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  title TEXT NOT NULL,
  slug TEXT NOT NULL UNIQUE,
  body TEXT NOT NULL,
  excerpt TEXT,
  tags TEXT DEFAULT '[]',
  featured_springs TEXT DEFAULT '[]',
  published_at DATETIME,
  author TEXT NOT NULL,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
, image_url TEXT, site TEXT, asana_task_gid TEXT, status TEXT DEFAULT 'published');
CREATE TABLE chat_rate_limits (ip TEXT PRIMARY KEY, count INTEGER NOT NULL DEFAULT 0, window_start INTEGER NOT NULL);
CREATE TABLE trails_cache (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  spring_slug TEXT NOT NULL,
  trail_id INTEGER NOT NULL,
  trail_name TEXT NOT NULL,
  trail_slug TEXT NOT NULL,
  alltrails_url TEXT NOT NULL,
  difficulty TEXT,
  length_miles REAL,
  elevation_gain_feet INTEGER,
  avg_rating REAL,
  photo_url TEXT,
  features TEXT,
  description TEXT,
  review_summary TEXT,
  distance_miles REAL,
  fetched_at TEXT NOT NULL,
  UNIQUE(spring_slug, trail_id)
);
CREATE TABLE system_state (
  key TEXT PRIMARY KEY,
  value TEXT NOT NULL,
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE spring_images (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  spring_slug TEXT NOT NULL,
  source TEXT NOT NULL,            -- wikimedia_commons | wikipedia | wikidata | flickr | openverse | google_places | operator
  image_url TEXT NOT NULL,         -- canonical full-size URL
  thumb_url TEXT,                  -- smaller preview URL when available
  license_code TEXT,               -- e.g. 'CC BY 2.0', 'CC0', 'PDM', 'Public domain'
  license_url TEXT,
  attribution TEXT,                -- creator / author
  source_url TEXT,                 -- foreign landing page (Commons/Flickr/Openverse page)
  provider_image_id TEXT,          -- dedup key: Commons pageid, Flickr photo id, Openverse uuid
  width INTEGER,
  height INTEGER,
  is_primary INTEGER DEFAULT 0,
  rank INTEGER DEFAULT 0,          -- within-spring ordering for a source
  captured_at TEXT,
  last_fetched TEXT DEFAULT (datetime('now'))
);
CREATE TABLE condition_reports (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  spring_slug TEXT NOT NULL,
  site TEXT NOT NULL,
  visitor_name TEXT,
  visit_date TEXT,
  temperature_observed INTEGER,
  flow_status TEXT,        -- flowing | low | dry | unknown
  crowd_level TEXT,        -- empty | moderate | busy | unknown
  access_status TEXT,      -- open | closed | road-issue | unknown
  body TEXT,
  photo_r2_key TEXT,
  status TEXT NOT NULL DEFAULT 'pending',  -- pending | approved | rejected
  submitter_ip TEXT,
  turnstile_ok INTEGER DEFAULT 0,
  created_at TEXT DEFAULT (datetime('now')),
  moderated_at TEXT
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_springs_slug ON springs(slug);
CREATE INDEX idx_springs_state ON springs(state);
CREATE INDEX idx_springs_region ON springs(region);
CREATE INDEX idx_springs_access_type ON springs(access_type);
CREATE INDEX idx_springs_development ON springs(development);
CREATE INDEX idx_springs_temperature ON springs(temperature_f);
CREATE INDEX idx_blog_posts_slug ON blog_posts(slug);
CREATE INDEX idx_blog_posts_published_at ON blog_posts(published_at);
CREATE INDEX idx_trails_cache_slug ON trails_cache(spring_slug);
CREATE INDEX idx_springs_vehicle ON springs(vehicle_requirement);
CREATE INDEX idx_springs_ferry ON springs(ferry_dependent);
CREATE INDEX idx_springs_crowding ON springs(crowding_pattern);
CREATE INDEX idx_blog_posts_site ON blog_posts(site);
CREATE INDEX idx_blog_posts_asana_task_gid ON blog_posts(asana_task_gid);
CREATE INDEX idx_blog_posts_status ON blog_posts(status);
CREATE INDEX idx_spring_images_slug ON spring_images(spring_slug);
CREATE INDEX idx_spring_images_slug_primary ON spring_images(spring_slug, is_primary);
CREATE UNIQUE INDEX uq_spring_images_provider_id ON spring_images(source, provider_image_id);
CREATE UNIQUE INDEX uq_spring_images_url ON spring_images(spring_slug, image_url);
CREATE INDEX idx_reports_slug_status ON condition_reports(spring_slug, status);
CREATE INDEX idx_reports_status ON condition_reports(status);
CREATE INDEX idx_reports_site ON condition_reports(site);
